#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const RELEASE='0.24.1';
const payload={"RELEASE_NOTES.md": "", "README.md": "", "RELEASE_NOTES_0.24.1.md": "", "package.json": "", "README_NASADENIE_0.24.1.txt": "", "src/lib/storage.ts": "", "src/data/seed.json": "", "src/views/ItCosts.tsx": "", "src/views/ItCosts.css": ""};

function findRoot(start) {
  let dir=path.resolve(start);
  for(let i=0;i<8;i++) {
    if(fs.existsSync(path.join(dir,'package.json')) && fs.existsSync(path.join(dir,'src'))) return dir;
    const parent=path.dirname(dir); if(parent===dir) break; dir=parent;
  }
  throw new Error('Nenašiel som koreň projektu (package.json + src). Spusti installer z koreňa projektu.');
}
function stamp() { return new Date().toISOString().replace(/[:.]/g,'-'); }
const root=findRoot(process.cwd());
const packagePath=path.join(root,'package.json');
let current='neznáma';
try { current=JSON.parse(fs.readFileSync(packagePath,'utf8')).version||current; } catch {}
console.log(`IS Riadenie odboru: upgrade ${current} -> ${RELEASE}`);
if(!String(current).startsWith('0.24.')) console.warn('Upozornenie: patch je určený primárne pre v0.24.x. Pokračujem bez databázovej migrácie.');
const backup=path.join(root,`backup-before-v0241-${stamp()}`);
fs.mkdirSync(backup,{recursive:true});
let written=0;
for(const [rel,encoded] of Object.entries(payload)) {
  const target=path.join(root,rel); const backupTarget=path.join(backup,rel);
  if(fs.existsSync(target)) { fs.mkdirSync(path.dirname(backupTarget),{recursive:true}); fs.copyFileSync(target,backupTarget); }
  fs.mkdirSync(path.dirname(target),{recursive:true});
  fs.writeFileSync(target,zlib.gunzipSync(Buffer.from(encoded,'base64')));
  console.log('OK ',rel); written++;
}
for(const cache of ['dist','.vite','node_modules/.vite']) {
  const target=path.join(root,cache); if(fs.existsSync(target)) fs.rmSync(target,{recursive:true,force:true});
}
const pkg=JSON.parse(fs.readFileSync(packagePath,'utf8'));
const itCosts=fs.readFileSync(path.join(root,'src/views/ItCosts.tsx'),'utf8');
if(pkg.version!==RELEASE) throw new Error(`Overenie zlyhalo: package.json má ${pkg.version}.`);
if(!itCosts.includes('itc-col-supplier') || !itCosts.includes('Podľa dodávateľa')) throw new Error('Overenie zlyhalo: nový stĺpec/filter dodávateľa sa nenašiel.');
console.log(`VERIFIED: release ${RELEASE} je nainštalované (${written} súborov).`);
console.log(`Záloha: ${backup}`);
console.log('Nový SQL nie je potrebný. Po deployi odporúčam Ctrl+F5.');
